//! The schema contributions of `services/configuration.ts`.
//! `schemas.json` is generated by `scripts/gen-schema-contributions.mjs`.

use crate::SchemaContributions;

pub fn schema_contributions() -> SchemaContributions {
    let schemas = serde_json::from_str(include_str!("schemas.json")).expect("valid schemas.json");
    SchemaContributions {
        schemas,
        schema_associations: Vec::new(),
    }
}
